#include <stdio.h>
void swap(int x, int y)
{
  int t;
  t = x;
  x = y;
  y = t;
}
int main(void)
{
  int a = 3, b = 5;
  swap(a, b);
  printf("%d %d\n", a, b);
  return 0;
}

#include <stdio.h>
int fun(int n)
{
  int s = 0;
  while (n > 0) {
    s += n % 10;
    n /= 10;
  }
  return s;
}
int main(void)
{
  printf("%d\n", fun(1234) + fun(56));
  return 0;
}

