#include <stdio.h>
void change(int b[], int n)
{
  int i;
  for (i = 0; i < n; i++)
    b[i] = b[i] * 2;
}
int main(void)
{
  int a[4] = {1, 2, 3, 4}, i;
  change(a, 4);
  for (i = 0; i < 4; i++)
    printf("%d ", a[i]);
  printf("\n");
  return 0;
}

