#include <stdio.h>
int isprime(int n)
{
  int i;
  if (n < 2)
    return 0;
  for (i = 2; i * i <= n; i++)
    if (n % i == 0)
      return 0;
  return 1;
}
int main(void)
{
  int n;
  for (n = 2; n < 100; n++)
    if (isprime(n))
      printf("%d ", n);
  printf("\n");
  return 0;
}

