#include <stdio.h>
int f(void)
{
  static int s = 0;
  int t = 0;
  s++;
  t++;
  return s * 10 + t;
}
int main(void)
{
  int i;
  for (i = 0; i < 3; i++)
    printf("%d ", f());
  printf("\n");
